# PlatformIO pre-build script: gzip web/index.html into include/web_index.h
# so the instructor UI is served straight from the firmware image.
import gzip
from pathlib import Path

Import("env")  # noqa: F821  (provided by PlatformIO/SCons)

root = Path(env["PROJECT_DIR"])  # noqa: F821
src = root / "web" / "index.html"
dst = root / "include" / "web_index.h"

if not dst.exists() or src.stat().st_mtime > dst.stat().st_mtime:
    data = gzip.compress(src.read_bytes(), 9, mtime=0)
    body = ",".join(str(b) for b in data)
    dst.write_text(
        "// Generated by scripts/embed_web.py from web/index.html - do not edit\n"
        "#pragma once\n#include <Arduino.h>\n"
        f"static const uint8_t WEB_INDEX_GZ[] PROGMEM = {{{body}}};\n"
        f"static const size_t WEB_INDEX_GZ_LEN = {len(data)};\n"
    )
    print(f"embed_web: {src.name} -> {dst.name} ({len(data)} bytes gz)")
